// ============================================================
// CONFIGURE: Add your Zoho OAuth credentials per service
// Each service maps to a different Zoho Self Client or scope.
// ============================================================
const SERVICES = {
  desk: {
    client_id: 'YOUR_CLIENT_ID',
    client_secret: 'YOUR_CLIENT_SECRET',
    refresh_token: 'YOUR_REFRESH_TOKEN',
    token_url: 'https://accounts.zoho.eu/oauth/v2/token' // .eu for EU, .com for US
  },
  crm: {
    client_id: 'YOUR_CRM_CLIENT_ID',
    client_secret: 'YOUR_CRM_CLIENT_SECRET',
    refresh_token: 'YOUR_CRM_REFRESH_TOKEN',
    token_url: 'https://accounts.zoho.eu/oauth/v2/token'
  },
  people: {
    client_id: 'YOUR_PEOPLE_CLIENT_ID',
    client_secret: 'YOUR_PEOPLE_CLIENT_SECRET',
    refresh_token: 'YOUR_PEOPLE_REFRESH_TOKEN',
    token_url: 'https://accounts.zoho.eu/oauth/v2/token'
  }
};

const TOKEN_TTL_MS = 50 * 60 * 1000; // 50 minutes (Zoho tokens last 60 min)
// ============================================================

const service = $input.first().json.service;

if (!service || !SERVICES[service]) {
  throw new Error(`Unknown service: ${service}. Available: ${Object.keys(SERVICES).join(', ')}`);
}

const config = SERVICES[service];
const staticData = $getWorkflowStaticData('global');
const cacheKey = `token_${service}`;
const expiryKey = `expiry_${service}`;

const cached = staticData[cacheKey];
const expiry = staticData[expiryKey] || 0;
const now = Date.now();

if (cached && now < expiry) {
  // Token still valid, return from cache
  return [{
    json: {
      access_token: cached,
      source: 'cache',
      service,
      expires_in_ms: expiry - now
    }
  }];
}

// Token expired or missing - need to refresh
return [{
  json: {
    needsRefresh: true,
    service,
    client_id: config.client_id,
    client_secret: config.client_secret,
    refresh_token: config.refresh_token,
    token_url: config.token_url,
    ttl: TOKEN_TTL_MS
  }
}];

// Cache the new token in Static Data
const refreshInput = $('Needs Refresh?').first().json;
const response = $input.first().json;

const token = response.access_token;
if (!token) {
  throw new Error('Failed to refresh token: ' + JSON.stringify(response));
}

const staticData = $getWorkflowStaticData('global');
const service = refreshInput.service;
staticData[`token_${service}`] = token;
staticData[`expiry_${service}`] = Date.now() + (refreshInput.ttl || 3000000);

return [{
  json: {
    access_token: token,
    source: 'refreshed',
    service
  }
}];
